local type W = require("wow")
local function f(v: W.Data | {W.MaybeSecret<number>}): {number}
   local s = v as W.Secret<{number}>
   if canaccessvalue(s) and not issecretvalue(s) then
      return s as {number}
   end
   return {}
end
local t: {W.MaybeSecret<number>} = { UnitHealth("player") }
local r = f(t)
print(r[1] + 1)

local type W = require("wow")
local store: {number} = {1}
local record Plain
   get: function(): {number}
end
local record Opq
   get: function(): {W.MaybeSecret<number>}
end
local p: Plain = { get = function(): {number} return store end }
local o = (p as any) as Opq
o.get()[1] = UnitHealth("player")
print(store[1] + 1)

