local type W = require("wow")
local record R
   k: any
end
local function f(g: function(): (number, W.Secret<number>))
   local a: {any} = { g(), 0 }
   local b: R = { k = g() }
   local c: {any} = { (g()) }
   local d: {integer: any} = { [1] = g() }
   print(a, b, c, d)
end
return f

